-- 3. Hand-added: the container a position left in. Not in the schema (see gateMovement.schema.ts),
--    so drizzle-kit does not know it and a later generate will not drop it.
ALTER TABLE "warehouse_gate_movement" ADD CONSTRAINT "wh_gate_movement_left_container_fk" FOREIGN KEY ("left_container_id") REFERENCES "public"."warehouse_container"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
-- 4. Pick-up PIN: outbound cargo of a position linked to a shipment remembers that shipment
--    (pickup_shipment_id), so its release needs the PIN line OK even if the link goes away; rows
--    made before the line existed get it now (the reads no longer add it).
UPDATE "warehouse_gate_movement" gm SET "pickup_shipment_id" = wt."shipment_id"
  FROM "warehouse_task" wt
  WHERE wt."id" = gm."warehouse_task_id" AND wt."shipment_id" IS NOT NULL AND wt."deleted_at" IS NULL AND gm."visit" = 'výdej';--> statement-breakpoint
UPDATE "warehouse_gate_movement" SET "release_gates" = "release_gates" || '[{"g": "Pick-up PIN verified", "s": "Pending", "note": "waiting for the driver''s PIN"}]'::jsonb
  WHERE "pickup_shipment_id" IS NOT NULL AND "imp_release" IS NULL AND "deleted_at" IS NULL
    AND NOT ("release_gates" @> '[{"g": "Pick-up PIN verified"}]'::jsonb);